<div class="page-title"><div><em>CUSTOMER CARE</em><h1>Support tickets</h1><p>Respond to customer questions and service requests.</p></div></div><?php if(!$tickets):?><div class="empty">No support tickets yet.</div><?php endif?><section class="panel list"><?php foreach($tickets as $t):?><div class="list-row"><span class="avatar"><?=initials($t['first_name'].' '.$t['last_name'])?></span><div><b><?=html_escape($t['subject'])?></b><small><?=html_escape($t['first_name'].' '.$t['last_name'])?> · <?=$t['reference']?> · <?=date('M j, g:i a',strtotime($t['updated_at']))?></small></div><span class="<?=status_class($t['priority'])?>"><?=ucfirst($t['priority'])?></span><span class="<?=status_class($t['status'])?>"><?=ucwords(str_replace('_',' ',$t['status']))?></span><a class="outline" href="<?=site_url('admin/tickets/'.$t['id'])?>">Open</a></div><?php endforeach?></section>
<?php if(isset($pagination)&&$pagination):?><div class="pager-wrap"><?=$pagination?></div><?php endif?>
